// @generated by:gauntlet run:godseye-local-inngest
import { randomBytes, randomUUID } from "node:crypto";
import { once } from "node:events";
import { createServer } from "node:http";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createInngestCell, type InngestCellOptions } from "../packages/core/src/inngest.js";
import { type JobsFixture, jobsFixture } from "./jobs-helpers.js";

describe("private cell Inngest worker boundary", () => {
  let fixture: JobsFixture;
  beforeEach(async () => {
    fixture = await jobsFixture();
  });
  afterEach(async () => fixture.store.close());
  const options = (): InngestCellOptions => ({
    id: "synthetic-cell-worker",
    authority: {
      projectId: fixture.project.id,
      environmentId: fixture.development.id,
      producerId: randomUUID(),
    },
    jobs: fixture.jobs(),
    baseUrl: "http://127.0.0.1:47881",
    sdkUrl: "http://127.0.0.1:47882/api/inngest",
    eventKey: randomBytes(32).toString("hex"),
    signingKey: randomBytes(32).toString("hex"),
  });

  it("T-E06-I01 rejects nonlocal and ambiguous authority endpoints before worker registration", () => {
    const input = options();
    for (const baseUrl of [
      "https://api.inngest.com",
      "http://example.test:8288",
      "http://127.0.0.1:8288?target=other",
      "http://synthetic:unused@127.0.0.1:8288",
    ])
      expect(() => createInngestCell({ ...input, baseUrl })).toThrow();
    for (const signingKey of ["", "odd", "f".repeat(63)])
      expect(() => createInngestCell({ ...input, signingKey })).toThrow();
  });

  it("T-E06-I02 refuses unsigned SDK execution and requests for another worker host", async () => {
    const input = options();
    const cell = createInngestCell(input);
    const body = JSON.stringify({ event: { name: "godseye/application.event", data: {} } });
    const unsigned = await cell.app.request(input.sdkUrl, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body,
    });
    expect(unsigned.status).toBe(401);
    const normalizedLoopback = await cell.app.request("http://localhost:47882/api/inngest", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body,
    });
    expect(normalizedLoopback.status).toBe(401);
    const foreign = await cell.app.request("http://127.0.0.1:47883/api/inngest", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body,
    });
    expect(foreign.status).toBe(403);
    expect((await fixture.jobs().overview(fixture.freshOwner())).runs).toHaveLength(0);
  });

  it("T-E06-I02 refuses an application envelope for a different producer before sending any HTTP request", async () => {
    const input = options();
    const cell = createInngestCell(input);
    const event = {
      id: randomUUID(),
      ...input.authority,
      producerId: randomUUID(),
      epoch: 1,
      userId: "synthetic-user",
      eventType: "document.updated",
      payload: {},
      occurredAt: fixture.clock.now().toISOString(),
    };
    await expect(cell.transport.send(event, new AbortController().signal)).rejects.toThrow(
      /producer.*cell/i,
    );
  });

  it("T-E06-B04 does not acknowledge source delivery merely because Inngest accepted an event", async () => {
    let requests = 0;
    const receiver = createServer((_request, response) => {
      requests++;
      response.setHeader("Content-Type", "application/json");
      response.end(JSON.stringify({ ids: ["synthetic-engine-accepted-only"] }));
    });
    receiver.listen(0, "127.0.0.1");
    await once(receiver, "listening");
    const address = receiver.address();
    if (!address || typeof address === "string")
      throw new Error("Synthetic receiver listener missing");
    try {
      const input = {
        ...options(),
        baseUrl: `http://127.0.0.1:${address.port}`,
        pollIntervalMs: 5,
      };
      const cell = createInngestCell(input);
      const event = {
        id: randomUUID(),
        ...input.authority,
        epoch: 1,
        userId: "synthetic-user",
        eventType: "document.updated",
        payload: {},
        occurredAt: fixture.clock.now().toISOString(),
      };
      await expect(cell.transport.send(event, AbortSignal.timeout(40))).rejects.toBeInstanceOf(
        Error,
      );
      expect(requests).toBe(1);
      expect(await fixture.jobs().applicationEventAccepted(input.authority, event)).toBe(false);
    } finally {
      receiver.closeAllConnections();
      await new Promise<void>((done, reject) =>
        receiver.close((error) => (error ? reject(error) : done())),
      );
    }
  });

  it("T-E06-I01 prevents foreign cron registration and excludes native-managed cron from the fixture calendar", async () => {
    const definition = await fixture.register({ trigger: { kind: "cron", cron: "* * * * *" } });
    const input = options();
    expect(() =>
      createInngestCell({
        ...input,
        cronDefinitions: [{ ...definition, environmentId: fixture.production.id }],
      }),
    ).toThrow(/another cell/i);
    const infrastructure = new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      jobs: {
        handlers: new Map([["fixture.work", fixture.handler]]),
        inngestEnvironmentIds: new Set([fixture.development.id]),
      },
    });
    fixture.clock.advance(60_000);
    await infrastructure.jobs.tick();
    expect((await infrastructure.jobs.overview(fixture.freshOwner())).runs).toHaveLength(0);

    const run = await infrastructure.jobs.triggerInngestCron(
      input.authority,
      definition.id,
      definition.hash,
      "synthetic-cron-event-1",
    );
    const replay = await infrastructure.jobs.triggerInngestCron(
      input.authority,
      definition.id,
      definition.hash,
      "synthetic-cron-event-1",
    );
    expect(replay.id).toBe(run.id);
    await infrastructure.jobs.pause(
      fixture.freshOwner(),
      definition.id,
      definition.revision,
      randomUUID(),
    );
    await expect(
      infrastructure.jobs.triggerInngestCron(
        input.authority,
        definition.id,
        definition.hash,
        "synthetic-cron-event-2",
      ),
    ).rejects.toMatchObject({ code: "FENCED" });
  });
});
